    local curType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if curType == Constants.IDType.QuestMain then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting750, "QuestRewardVo", questId)
    elseif curType == Constants.IDType.QuestMainChallenge then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting6125, "QuestRewardVo", questId)
    elseif curType == Constants.IDType.QuestDaily or curType == Constants.IDType.QuestCoinsCopy or curType == Constants.IDType.QuestExpCopy or curType == Constants.IDType.QuestUpStarCopy then
