--[[
    @desc: 获取关卡的奖励配表数据
    author:{author}
    time:2020-07-19 16:08:32
    --@questId: 关卡id
	--@rewardType: 奖励类型
    --@isNotSort: 不排序
    @return:
]]
function RewardConfMgr:GetQuestRewardData(questId, rewardType, isNotSort)
    if not questId or not rewardType then return nil end
    questId = checkNumber(questId)
    rewardType = checkNumber(rewardType)
    local vo = self:GetQuestRewardVo(questId)

    return self:CheckVoRewardData(vo, rewardType, isNotSort)
end

--分析vo中的reward数据
function RewardConfMgr:CheckVoRewardData(vo, rewardType, isNotSort)
    if not vo then return nil end

    local rewardData
    local rewardNums 
    local rewardProbabilitys
    if checkNumber(rewardType) == Constants.QuestRewardType.FristRewards then
        if checkString(vo.fristRewards) ~= "0" and checkString(vo.fristRewards) ~= "" then
            rewardData = string.split(vo.fristRewards, ";")
        end
        if checkString(vo.fristRewardsNum) ~= "0" and checkString(vo.fristRewardsNum) ~= "" then
            rewardNums = string.split(vo.fristRewardsNum, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.StarRewardId then
        if checkString(vo.starRewardId) ~= "0" and checkString(vo.starRewardId) ~= "" then
            rewardData = string.split(vo.starRewardId, ";")
        end
        if checkString(vo.starRewardNum) ~= "0" and checkString(vo.starRewardNum) ~= "" then
            rewardNums = string.split(vo.starRewardNum, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.RegularReward then
        if checkString(vo.regularReward) ~= "0" and checkString(vo.regularReward) ~= "" then
            rewardData = string.split(vo.regularReward, ";")
        end
        if checkString(vo.regularRewardNum) ~= "0" and checkString(vo.regularRewardNum) ~= "" then
            rewardNums = string.split(vo.regularRewardNum, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.RareReward then
        if checkString(vo.rewardID) ~= "0" and checkString(vo.rewardID) ~= "" then
            rewardData = string.split(vo.rewardID, ";")
        end
        if checkString(vo.rewardNum) ~= "0" and checkString(vo.rewardNum) ~= "" then
            rewardNums = string.split(vo.rewardNum, ";")
        end
        --没有数量
        --rewardNums = {}

    elseif checkNumber(rewardType) == Constants.QuestRewardType.CopperBox then
        if checkString(vo.cRewardItem) ~= "0" and checkString(vo.cRewardItem) ~= "" then
            rewardData = string.split(vo.cRewardItem, ";")
        end
        if checkString(vo.cRewardNum) ~= "0" and checkString(vo.cRewardNum) ~= "" then
            rewardNums = string.split(vo.cRewardNum, ";")
        end
        if checkString(vo.cRewardItemRandom) ~= "0" and checkString(vo.cRewardItemRandom) ~= "" then
            rewardProbabilitys = string.split(vo.cRewardItemRandom, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.SilverBox then
        if checkString(vo.sRewardItem) ~= "0" and checkString(vo.sRewardItem) ~= "" then
            rewardData = string.split(vo.sRewardItem, ";")
        end
        if checkString(vo.sRewardNum) ~= "0" and checkString(vo.sRewardNum) ~= "" then
            rewardNums = string.split(vo.sRewardNum, ";")
        end
        if checkString(vo.sRewardItemRandom) ~= "0" and checkString(vo.sRewardItemRandom) ~= "" then
            rewardProbabilitys = string.split(vo.sRewardItemRandom, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.GoldBox then
        if checkString(vo.gRewardItem) ~= "0" and checkString(vo.gRewardItem) ~= "" then
            rewardData = string.split(vo.gRewardItem, ";")
        end
        if checkString(vo.gRewardNum) ~= "0" and checkString(vo.gRewardNum) ~= "" then
            rewardNums = string.split(vo.gRewardNum, ";")
        end
        if checkString(vo.gRewardItemRandom) ~= "0" and checkString(vo.gRewardItemRandom) ~= "" then
            rewardProbabilitys = string.split(vo.gRewardItemRandom, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.Captain then
        if checkString(vo.leaderRewardItem) ~= "0" and checkString(vo.leaderRewardItem) ~= "" then
            rewardData = string.split(vo.leaderRewardItem, ";")
        end
        if checkString(vo.leaderRewardNum) ~= "0" and checkString(vo.leaderRewardNum) ~= "" then
            rewardNums = string.split(vo.leaderRewardNum, ";")
        end
        if checkString(vo.leaderRewardRandom) ~= "0" and checkString(vo.leaderRewardRandom) ~= "" then
            rewardProbabilitys = string.split(vo.leaderRewardRandom, ";")
        end
    elseif checkNumber(rewardType) == Constants.QuestRewardType.Raid then
        if checkString(vo.raidRewardID) ~= "0" and checkString(vo.raidRewardID) ~= "" then
            rewardData = string.split(vo.raidRewardID, ";")
        end
        if checkString(vo.raidRewardNum) ~= "0" and checkString(vo.raidRewardNum) ~= "" then
            rewardNums = string.split(vo.raidRewardNum, ";")
        end
    end

    return self:_GetRewardData(rewardData, rewardNums, isNotSort, rewardProbabilitys)
end

--[[
    @desc: 获取编队界面显示的奖励物品
    author:{author}
    time:2020-07-19 17:33:46
    --@questId: 关卡ID
    @return:
]]
function RewardConfMgr:GetTeamShowRewardData(questId)
    local t = {}
    if not questId then return t end
    local vo = self:GetQuestRewardVo(questId)
    if not vo then return t end

    local items = CfUtils.Split(vo.showItem)
    local showItemTags = CfUtils.Split(vo.showItemTag)
    local showItemNums = CfUtils.Split(vo.showItemNum)

    if items and showItemTags and showItemNums then
        for i = 1, #items do
            local id = items[i]
            --local tagName = self:GetTeamShowRewardTagName(showItemTags[i])
            local reward = {
                ["id"] = checkNumber(id),
                ["num"] = checkNumber(showItemNums[i]),
                ["type"] = checkNumber(showItemTags[i]),
            }
            if checkNumber(id) > 0 then
                table.insert(t, reward)
            end
        end 
    end
    return t
end


--- GetTeamShowRewardDataAndHandleSpecialType
--- 获取编队界面显示的奖励并且处理特殊类型
---@param questId number 关卡id
function RewardConfMgr:GetTeamShowRewardDataAndHandleSpecialType(questId)
    local rewardData = self:GetTeamShowRewardData(questId)
    if not rewardData then
        return
    end
    local t = {}
    local count = 1
    for i = 1, #rewardData do
        if count < 4 then
            local data = rewardData[i]
            if data.type == Constants.TeamShowRewardType.StarType then
                --领取过的不显示
                if not QuestConfMgr:GetInstance():IsPassAndCompleteAllCdtQuest(questId) then
                    table.insert(t, rewardData[i])
                    count = count + 1
                end
            elseif data.type == Constants.TeamShowRewardType.FristType then
                --领取过的不显示
                if not QuestConfMgr:GetInstance():IsPassQuest(questId) then
                    table.insert(t, rewardData[i])
                    count = count + 1
                end
            else
                table.insert(t, rewardData[i])
                count = count + 1
            end
        end
    end

    return t

end

--[[
    @desc: 编队界面显示奖励的名字
    author:{author}
    time:2020-07-19 17:44:52
    --@type: 
    @return:
]]
function RewardConfMgr:GetTeamShowRewardTagName(type)
    type = checkNumber(type)
    if type == 1 then
        return localize("必定掉落")
    elseif type == 2 then
        return localize("概率掉落")
    elseif type == 3 then
        return localize("首次通关掉落")
    elseif type == 4 then
        return localize("三星奖励")
    elseif type == 5 then
        return localize("队长奖励")
    elseif type == 6 then
        return localize("扫荡奖励")
    end
    
    return ""
end

--[[
    @desc: 构造奖励数据
    author:{author}
    time:2020-07-19 16:56:45
    --@rewards: 
	--@rewardNums: 
    @return:
]]
function RewardConfMgr:_GetRewardData(rewards, rewardNums, isNotSort, probabilitys)
    rewards = checkTable(rewards)
    rewardNums = checkTable(rewardNums)
    probabilitys = checkTable(probabilitys)
    if #rewards <= 0 then
        return {}
    end

    local rewardDatas = {}
    for i = 1, #rewards do
        local id = rewards[i]
        if checkNumber(id) > 0 then
            local reward = {
                ["id"] = id,
                ["goodsId"] = id,
                ["num"] = checkNumber(rewardNums[i]),
                ["probability"] = checkNumber(probabilitys[i])
            }

            table.insert(rewardDatas, reward)
        end
    end 

    if isNotSort then
        return rewardDatas
    end
    return self:SortRewards(rewardDatas)
end

--奖励排序规则
function RewardConfMgr:SortRewards(items)
    if not items or #items <= 0 then
        return items
    end
    local itemsReturn = clone(items)
    --[[
    table.sort(itemsReturn, function(a, b)
        local item1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.id)
        local item2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.id)

        if not item1 then 
            return true
        elseif not item2 then
            return false
        end

        if checkNumber(item1.quality) > checkNumber(item2.quality) then 
            return true
        elseif checkNumber(item1.quality) == checkNumber(item2.quality) then
            if checkNumber(a.id) < checkNumber(b.id) then
                return true
            end
        end
        return false
    end)
    ]]
    return itemsReturn
end

return RewardConfMgr
